repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('data', 22), ('data', 31), ('web', 49), ('ops', 28), ('web', 27), ('data', 4)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

