"""Share of the total hours per ticket."""
from tickets import load_tickets


def hours_shares(tickets):
    """Return each ticket's share of the total hours, in order."""
    total = sum(x.hours for x in tickets)
    return [x.hours / total for x in tickets]


def stored_shares():
    """Shares for the stored tickets."""
    return hours_shares(load_tickets())


def top_share(tickets):
    """Return the largest share, or 0.0 when there are no tickets."""
    shares = hours_shares(tickets)
    return max(shares) if shares else 0.0


def describe_ticket(ticket):
    """Return a one-line description of a ticket."""
    return "%s: %s" % (ticket.team, ticket.hours)

